use crate::{ivp_managed_response::{ResponseWorld,Body,Object,Feature,Settings},ivp_contact_pipeline::CoreFrame,ivp_contact::Core,ivp_create::{Endpoint,Feature as CompactFeature},ivp_managed_contacts::Settings as AdmissionSettings,ivp_refresh,ivp_unit_registry::Registry};
use bevy::prelude::*;
use serde_json::Value;
fn f(v:&Value)->f32{v.as_f64().unwrap() as f32}
fn vec(v:&Value)->Vec3{Vec3::from_array(std::array::from_fn(|i|f(&v[i])))}
fn rows(v:&Value)->[Vec3;3]{std::array::from_fn(|i|vec(&v[i]))}
fn endpoint(e:&Value)->Endpoint{let v=&e["feature"];Endpoint{object:e["object"].as_u64().unwrap(),feature:CompactFeature{kind:v["kind"].as_i64().unwrap() as i16,edge:v["edge"].as_u64().unwrap(),opposite:v["opposite"].as_u64().unwrap(),triangle:v["triangle"].as_u64().unwrap(),ledge:v["ledge"].as_u64().unwrap(),vertex:v["vertex"].as_u64().unwrap() as u16,vertices:rows(&v["vertices"])}}}
fn world(c:&Value)->ResponseWorld{
    let mut registry=Registry::new(4);let bodies=c["bodies"].as_array().unwrap().iter().enumerate().map(|(i,v)|{let flags=v["flags"].as_u64().unwrap() as u16;registry.register_core(i,flags&2!=0).unwrap();Body{flags,core:Core{inverse_mass:f(&v["inverse_mass"]),inverse_inertia:vec(&v["inverse_inertia"]),linear:vec(&v["linear"]),angular:vec(&v["angular"]),pending_linear:vec(&v["pending_linear"]),pending_angular:vec(&v["pending_angular"])},frame:CoreFrame{rotation:Mat3::from_cols_array_2d(&rows(&v["rotation"]).map(|v|v.to_array())).transpose(),position:vec(&v["position"])},stamps:std::array::from_fn(|i|v["stamps"][i].as_f64().unwrap())}}).collect();
    let mut objects=std::collections::BTreeMap::new();for birth in c["births"].as_array().unwrap(){for side in 0..2{let e=&birth["endpoints"][side];let core=e["object"].as_u64().unwrap() as usize-1;let shape=&birth["shapes"][side];let m=&c["bodies"][core]["material"];let o=Object{core,rotation:rows(&shape["rotation"]),translation:vec(&shape["translation"]),radius:f(&shape["radius"]),material_flags:m["flags"].as_u64().unwrap() as u32,friction:f(&m["friction"])};if let Some(old)=objects.insert(core as u64+1,o){assert_eq!(old.rotation,o.rotation);assert_eq!(old.translation,o.translation);assert_eq!(old.radius,o.radius);}}}
    let k=&c["settings"];ResponseWorld::new(registry,bodies,objects,Settings{dt:f(&c["dt"]),admission:AdmissionSettings{distance:f(&k["distance"]),area_epsilon:k["area_epsilon"].as_f64().unwrap()},refresh:ivp_refresh::Settings{epsilon:f(&k["epsilon"]),bary_bias:f(&k["bary_bias"]),area_epsilon:k["area_epsilon"].as_f64().unwrap(),one:f(&k["one"]),opposite:f(&k["opposite"])},threshold_extra:f(&k["threshold_extra"]),minimum_impulse:f(&k["minimum_impulse"]),minimum_determinant_squared:f(&k["minimum_determinant_squared"])},c["time"].as_f64().unwrap()).unwrap()
}
fn features(c:&Value)->[Feature;2]{std::array::from_fn(|i|Feature{endpoint:endpoint(&c["endpoints"][i]),vertices:rows(&c["shapes"][i]["vertices"]),canonical:rows(&c["shapes"][i]["canonical"])})}
fn compare(a:&Value,b:&Value,path:&str){match(a,b){
    (Value::Object(a),Value::Object(b))=>for(k,v)in a{compare(v,&b[k],&format!("{path}.{k}"));},
    (Value::Array(a),Value::Array(b))=>{assert_eq!(a.len(),b.len(),"{path}");for(i,(a,b))in a.iter().zip(b).enumerate(){compare(a,b,&format!("{path}[{i}]"));}},
    (Value::Number(a),Value::Number(b))=>{if path.ends_with(".time")||path.contains(".stamps["){assert_eq!(a.as_f64().unwrap().to_bits(),b.as_f64().unwrap().to_bits(),"{path}");}else if a.is_f64()||b.is_f64(){assert_eq!((a.as_f64().unwrap() as f32).to_bits(),(b.as_f64().unwrap() as f32).to_bits(),"{path}: {a} vs {b}");}else{assert_eq!(a,b,"{path}");}},
    _=>assert_eq!(a,b,"{path}"),
}}

fn configured(c:&Value)->ResponseWorld{let mut b=c.clone();b["endpoints"]=c["births"][0]["endpoints"].clone();b["shapes"]=c["births"][0]["shapes"].clone();world(&b).with_energy(c["bodies"].as_array().unwrap().iter().map(|v|crate::ivp_batch_normal::Physical{flags:v["flags"].as_u64().unwrap() as u16,mass:f(&v["mass"]),inertia:vec(&v["inertia"])}).collect(),f(&c["allowance_factor"]),f(&c["energy_bound"])).unwrap()}

pub(crate) fn configured_pipeline(c:&Value)->ResponseWorld{let w=&c["work"];let k=&w["settings"];configured(c).with_pair_work(f(&w["coefficient"]),f(&w["initial"]),w["blocked"].as_array().unwrap().iter().map(|b|b.as_bool().unwrap()).collect(),crate::ivp_dissipation::Settings{epsilon:f(&k["epsilon"]),one:f(&k["one"]),opposite:f(&k["opposite"]),two:f(&k["two"]),half:f(&k["half"]),huge:f(&k["huge"]),small:f(&k["small"]),fraction:f(&k["fraction"])}).unwrap()}
pub(crate) fn replay_pipeline(c:&Value,check:bool)->Vec<Value>{let mut w=configured_pipeline(c);let mut all=vec![];
for b in c["births"].as_array().unwrap(){let mut input=c.clone();input["endpoints"]=b["endpoints"].clone();input["shapes"]=b["shapes"].clone();let id=w.resolve(0xc0000,features(&input),Some(1)).unwrap().unwrap();let actual=w.snapshot(id);if check{compare(&actual,&b["numeric"],"pipeline admission");}all.push(actual);}
let actual=w.pipeline_snapshot(0);if check{compare(&actual,&c["states"][0]["output"],"pipeline initial");}all.push(actual);w.take_effects();
for(i,row)in c["states"].as_array().unwrap().iter().enumerate().skip(1){let mut changes=vec![crate::ivp_managed_response::StepChange{core:1,linear:vec(&row["kick"]),angular:vec(&row["angular"]),translation:vec(&row["shift"])}];if let Some(shift)=row.get("upper_shift"){if vec(shift)!=Vec3::ZERO{changes.push(crate::ivp_managed_response::StepChange{core:2,linear:Vec3::ZERO,angular:Vec3::ZERO,translation:vec(shift)});}}w.advance_many(&changes).unwrap();w.refresh(0).unwrap();let refresh=w.pipeline_snapshot(0);w.tangent(0).unwrap();let tangent=w.pipeline_snapshot(0);let retired=w.normal(0).unwrap();assert_eq!(retired,i==13);let normal=w.pipeline_snapshot(0);for(phase,a)in [&refresh,&tangent,&normal].into_iter().enumerate(){if check{compare(a,&row["phases"][phase],&format!("world{} pipeline{i} phase{phase}",c["scenario"]));}}all.extend([refresh,tangent,normal]);}
let(effects,ids,features)=w.take_effects();assert_eq!(ids.len(),c["births"].as_array().unwrap().len());assert_eq!(features.len(),ids.len());assert_eq!(effects.iter().filter(|e|matches!(e,crate::ivp_unit_registry::Effect::ResetClock(_))).count(),2*ids.len());all}
pub(crate) fn verify(){let data:Value=serde_json::from_str(include_str!("../tools/fixtures/native-ivp-contact-batch-pipeline.json")).unwrap();let mut count=0;for c in data["cases"].as_array().unwrap(){let actual=replay_pipeline(c,true);count+=actual.len();let mut corrupt=c.clone();for b in corrupt["births"].as_array_mut().unwrap(){b["numeric"]=Value::Null;}corrupt["states"][0]["output"]=Value::Null;for row in corrupt["states"].as_array_mut().unwrap().iter_mut().skip(1){row["phases"]=Value::Null;}assert_eq!(actual,replay_pipeline(&corrupt,false));}assert_eq!(count,336);println!("complete coupled controller sequence:8 native worlds /104 sequences /336 checkpoints; retained pair clocks, work, raw/pending velocities and retirement match");}
#[test]fn native_coupled_refresh_friction_normal_sequence_matches(){verify();}

pub(crate) fn verify_stack(){let data:Value=serde_json::from_str(include_str!("../tools/fixtures/native-ivp-contact-stack-pipeline.json")).unwrap();let mut count=0;for c in data["cases"].as_array().unwrap(){let actual=replay_pipeline(c,true);count+=actual.len();let mut corrupt=c.clone();for b in corrupt["births"].as_array_mut().unwrap(){b["numeric"]=Value::Null;}corrupt["states"][0]["output"]=Value::Null;for row in corrupt["states"].as_array_mut().unwrap().iter_mut().skip(1){row["phases"]=Value::Null;}assert_eq!(actual,replay_pipeline(&corrupt,false));}assert_eq!(count,354);println!("shared-core coupled controller sequence:8 native worlds /2 pairs /354 checkpoints match without later reseeding");}
#[test]fn native_shared_core_stack_controller_sequence_matches(){verify_stack();}

pub(crate) fn invalid_pipeline(){let d:Value=serde_json::from_str(include_str!("../tools/fixtures/native-ivp-contact-batch-pipeline.json")).unwrap();let c=&d["cases"][0];let mut w=configured_pipeline(c);for b in c["births"].as_array().unwrap(){let mut input=c.clone();input["endpoints"]=b["endpoints"].clone();input["shapes"]=b["shapes"].clone();w.resolve(0xc0000,features(&input),Some(1)).unwrap();}let before=(w.pipeline_snapshot(0),w.diagnostics());assert!(w.tangent(0).is_err());assert!(w.normal(0).is_err());let change=crate::ivp_managed_response::StepChange{core:1,linear:Vec3::ZERO,angular:Vec3::ZERO,translation:Vec3::ZERO};assert!(w.advance_many(&[change,change]).is_err());assert_eq!(before,(w.pipeline_snapshot(0),w.diagnostics()));
 w.advance(1,Vec3::splat(f32::MAX/4.),Vec3::ZERO,Vec3::ZERO).unwrap();let before=(w.pipeline_snapshot(0),w.diagnostics());assert!(w.refresh(0).is_err());assert_eq!(before,(w.pipeline_snapshot(0),w.diagnostics()));}
#[test]fn coupled_pipeline_phase_and_late_work_errors_are_atomic(){invalid_pipeline();}
